  static const double xs = 4, sm = 8, md = 10, lg = 16, xl = 28, full = 999, controlApple = 6;

  /// An app icon's corner in a grid, for an icon [size] across.
  static double tile(double size) => size * 0.25;
}

/// Elevation levels 0 to 3: shadows, and in dark a lighter surface and a
/// 1 px outline, since shadows do not show on dark.
abstract final class ClaxElevation {
  /// The shadows of [level] in brightness [b].
  static List<BoxShadow> shadows(int level, Brightness b) => switch ((level, b)) {
      (0, _) => const [],
      (1, Brightness.light) => const [BoxShadow(color: Color(0x0F14140F), offset: Offset(0, 1), blurRadius: 2), BoxShadow(color: Color(0x0D14140F), offset: Offset(0, 4), blurRadius: 16)],
      (2, Brightness.light) => const [BoxShadow(color: Color(0x1414140F), offset: Offset(0, 2), blurRadius: 6), BoxShadow(color: Color(0x1A14140F), offset: Offset(0, 8), blurRadius: 24)],
      (3, Brightness.light) => const [BoxShadow(color: Color(0x0F14140F), offset: Offset(0, 2), blurRadius: 6), BoxShadow(color: Color(0x1F14140F), offset: Offset(0, 16), blurRadius: 40)],
      (1, Brightness.dark) => const [BoxShadow(color: Color(0x66000000), offset: Offset(0, 1), blurRadius: 2)],
      (2, Brightness.dark) => const [BoxShadow(color: Color(0x73000000), offset: Offset(0, 2), blurRadius: 6), BoxShadow(color: Color(0x80000000), offset: Offset(0, 8), blurRadius: 24)],
      (3, Brightness.dark) => const [BoxShadow(color: Color(0x66000000), offset: Offset(0, 2), blurRadius: 6), BoxShadow(color: Color(0x80000000), offset: Offset(0, 16), blurRadius: 40)],
      _ => throw RangeError.range(level, 0, 3, 'level'),
    };

  /// A surface at [level]: [color] or the level's surface, its shadows and,
  /// in dark, its outline (`border` at 1, `borderHover` above).
  static BoxDecoration of(int level, Brightness b, ClaxPalette p, {Color? color, BorderRadius? radius}) {
    final surface = switch (level) {
      0 => p.bg,
      1 => p.card,
      2 => p.overlay,
      3 => p.raised,
      _ => throw RangeError.range(level, 0, 3, 'level'),
    };
    final outline = level == 0 || b == Brightness.light
        ? null
        : switch (level) {
          1 => p.border,
          2 => p.borderHover,
          3 => p.borderHover,
          _ => null,
        };
    return BoxDecoration(
      color: color ?? surface,
      borderRadius: radius,
      border: outline == null ? null : Border.all(color: outline),
      boxShadow: shadows(level, b),
    );
  }
}

/// Durations and curves.
abstract final class ClaxMotion {
  static const fast = Duration(milliseconds: 120), base = Duration(milliseconds: 200), enter = Duration(milliseconds: 300), exit = Duration(milliseconds: 200), markBreath = Duration(milliseconds: 1600);
  static const Curve standard = Cubic(0.4, 0, 0.2, 1);
  static const Curve decelerate = Cubic(0.05, 0.7, 0.1, 1);
  static const Curve accelerate = Cubic(0.3, 0, 0.8, 0.15);

  /// [d], or 120 ms when animations are reduced and [d] is longer.
  static Duration of(BuildContext context, Duration d) {
    const reduced = Duration(milliseconds: 120);
    return MediaQuery.disableAnimationsOf(context) && d > reduced ? reduced : d;
  }
}

/// The Clax mark's shapes in its [width] by [height] box: the person's arc
/// ([you]) at the left and Clax's ([agent]) at the right, each bulging
/// toward the [dot] between them, stroked [stroke] wide with [cap] ends.
abstract final class ClaxMarkGeometry {
  static const double width = 22, height = 16, stroke = 2.6;
  static const StrokeCap cap = StrokeCap.round;
  static const Offset dot = Offset(11, 8);
  static const double dotRadius = 1.7;

  /// The person's arc.
  static Path you() => Path()..moveTo(1.5, 2.5)..arcToPoint(const Offset(1.5, 13.5), radius: const Radius.elliptical(5.5, 5.5), rotation: 0, largeArc: false, clockwise: true);

  /// Clax's arc.
  static Path agent() => Path()..moveTo(20.5, 2.5)..arcToPoint(const Offset(20.5, 13.5), radius: const Radius.elliptical(5.5, 5.5), rotation: 0, largeArc: false, clockwise: false);
}
